"""Standalone Antillia case-study pages, built from recorded experiment results."""
from pathlib import Path
import json,html,shutil,math
from case_content import CASES
R=Path(__file__).resolve().parents[1];A=R/'case-study-assets';A.mkdir(exist_ok=True)
evidence=json.loads((A/'model-evidence.json').read_text(encoding='utf8'))
def esc(x):return html.escape(str(x),quote=True)
def tr(v,tag='span',cls=''):
    return f'<{tag} class="{cls}" data-pl="{esc(v[0])}" data-en="{esc(v[1])}">{esc(v[0])}</{tag}>'
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def svg_head(label,w=900,h=320):return f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-label="{esc(label)}"><rect width="100%" height="100%" rx="16" fill="#181c22"/>'
def architecture(c):
    s=svg_head(c['name']+' model architecture',1000,270)+'<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#66dece"/></marker></defs>'
    for i,(name,desc) in enumerate(c['layers']):
        x=22+i*196
        if i<4:s+=f'<path class="signal" d="M{x+174} 132H{x+192}" stroke="#66dece" stroke-width="1.4" marker-end="url(#arrow)"/>'
        s+=f'<rect x="{x}" y="65" width="172" height="135" rx="9" fill="#20262d" stroke="{"#ff681f" if i in [2,4] else "#39424b"}"/><text x="{x+16}" y="92" fill="#66dece" font-family="sans-serif" font-size="10">0{i+1}</text><text x="{x+16}" y="129" fill="#f4f2ee" font-family="sans-serif" font-size="16">{esc(name)}</text>'
        words=desc.split();lines=[''];
        for word in words:
            if len(lines[-1]+' '+word)>22:lines.append(word)
            else:lines[-1]+=(' ' if lines[-1] else '')+word
        for j,line in enumerate(lines[:3]):s+=f'<text x="{x+16}" y="{153+j*15}" fill="#aeb8bf" font-family="sans-serif" font-size="10">{esc(line)}</text>'
    return s+'</svg>'
def model_visual(c):
    d=evidence[c['slug']];s=svg_head(c['name']+' actual model evidence',800,410)
    if d['kind']=='heatmap':
        m=d['values'];maximum=max(abs(v) for row in m for v in row) or 1;rows=len(m);cols=len(m[0]);cw=690/cols;ch=300/rows
        for y,row in enumerate(m):
            for x,v in enumerate(row):
                a=min(abs(v)/maximum,1);target=(255,104,31) if v>=0 else (102,222,206);base=(28,34,42);color='rgb('+','.join(str(round(base[k]+(target[k]-base[k])*a)) for k in range(3))+')'
                s+=f'<rect x="{55+x*cw:.2f}" y="{35+y*ch:.2f}" width="{cw-.6:.2f}" height="{ch-.6:.2f}" fill="{color}"><title>{v:.6f}</title></rect>'
        s+='<text x="55" y="376" fill="#66dece" font-family="sans-serif" font-size="12">negative weights</text><text x="604" y="376" fill="#ff681f" font-family="sans-serif" font-size="12">positive weights</text>'
    elif d['kind']=='filters':
        for i,f in enumerate(d['values']):
            ox=42+(i%8)*91;oy=28+(i//8)*89
            for y,row in enumerate(f):
                for x,rgb in enumerate(row):s+=f'<rect x="{ox+x*10}" y="{oy+y*10}" width="10" height="10" fill="rgb({",".join(map(str,rgb))})"/>'
            s+=f'<text x="{ox}" y="{oy+82}" fill="#aeb8bf" font-family="sans-serif" font-size="9">filter {i+1:02d}</text>'
    else:
        pts=d['points'];xs=[p['x'] for p in pts];ys=[p['y'] for p in pts];dx=max(xs)-min(xs) or 1;dy=max(ys)-min(ys) or 1
        s+='<path d="M55 340H750M55 340V30" stroke="#45505a" fill="none"/>'
        for p in pts:
            x=80+(p['x']-min(xs))/dx*635;y=320-(p['y']-min(ys))/dy*260;color='#ff681f' if p['language']=='pl' else '#66dece'
            s+=f'<circle cx="{x:.1f}" cy="{y:.1f}" r="7" fill="{color}" opacity=".85"><title>{esc(p["title"])}</title></circle>'
        s+='<text x="55" y="380" fill="#ff681f" font-family="sans-serif" font-size="12">PL</text><text x="100" y="380" fill="#66dece" font-family="sans-serif" font-size="12">EN</text><text x="550" y="380" fill="#aeb8bf" font-family="sans-serif" font-size="12">PCA · 384D → 2D</text>'
    return s+'</svg>'
def benchmark(c):
    p=R/c['folder'];slug=c['slug'];m=read(next(x for x in [p/'artifacts/metrics.json',p/'reports/metrics.json'] if x.exists())) if slug!='ai-desk' else read(p/'evaluation/live-results.json')
    if slug=='demandcast':rows=[('Seasonal naive',m['test']['seasonal']['MAE']),('Gradient boosting',m['test']['boosting']['MAE']),('GRU',m['test']['gru']['MAE'])];metric='MAE ↓';hero=f'{rows[0][1]:.1f}';unit=('wypożyczeń / h · MAE','rentals / h · MAE');scope=('102 okna testowe · 24 h','102 test windows · 24 h')
    elif slug=='basketwise':rows=[('Popularity',m['test']['popularity']['NDCG@10']),('Item-to-item',m['test']['item_item']['NDCG@10']),('Factorization',m['test']['factorization']['NDCG@10'])];metric='NDCG@10 ↑';hero=f'{rows[-1][1]:.3f}';unit=('NDCG@10 · test offline','NDCG@10 · offline test');scope=('1426 użytkowników testowych','1,426 test users')
    elif slug in ['intentroute','reviewpulse']:rows=[('TF-IDF baseline',m['models']['tfidf']['test']['macro_f1']*100),('MiniLM + MLP',m['models']['embedding_mlp']['test']['macro_f1']*100)];metric='Macro F1 (%) ↑';hero=f'{rows[-1][1]:.1f}%';unit=('Macro F1 · test angielski','Macro F1 · English test');scope=(f'{m["split_counts"]["test"]} przykładów testowych',f'{m["split_counts"]["test"]} test examples')
    elif slug=='terravision':rows=[('Extra Trees',m['models']['baseline']['accuracy']*100),('ResNet18',m['models']['resnet18']['accuracy']*100)];metric='Accuracy (%) ↑';hero=f'{rows[-1][1]:.2f}%';unit=('Accuracy · EuroSAT RGB','Accuracy · EuroSAT RGB');scope=('4050 obrazów testowych','4,050 test images')
    elif slug=='machinesentinel':rows=[('Isolation Forest',m['models']['isolationforest']['pr_auc']),('Autoencoder',m['models']['autoencoder']['pr_auc'])];metric='PR-AUC ↑';hero=f'{rows[-1][1]:.3f}';unit=('PR-AUC · test AI4I','PR-AUC · AI4I test');scope=('1500 odczytów · dane syntetyczne','1,500 readings · synthetic data')
    else:rows=[('Completed live streams',sum(r.get('transport_pass',False) for r in m['results'])),('Retrieval checks passed',m['retrieval_pass'])];metric='Cases / 70';hero=f'{m["retrieval_pass"]}/70';unit=('kontroli retrieval','retrieval checks');scope=('70 scenariuszy aplikacyjnych','70 application scenarios')
    return rows,metric,hero,unit,scope
ARROW='<svg class="arrow" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>'
def header():return '<a class="skip-link" href="#main">Przejdź do treści</a><header class="site-header"><div class="header-inner"><a class="brand" href="https://antillia.tech"><svg class="mark" viewBox="0 0 24 32" aria-hidden="true"><path d="M10 0h14L14 32H0z" fill="currentColor"/></svg><span>Antillia</span></a><nav class="desktop-nav"><a href="index.html">Portfolio</a><a href="#results">'+tr(('Wyniki','Results'))+'</a><a href="#model">'+tr(('Model','Model'))+'</a><a href="#uses">'+tr(('Zastosowania','Use cases'))+'</a></nav><div class="header-end"><div class="language"><button data-lang="pl" aria-pressed="true">PL</button><span>/</span><button data-lang="en" aria-pressed="false">EN</button></div><a class="header-contact" href="https://antillia.tech/#contact">'+tr(('Porozmawiajmy','Let’s talk'))+ARROW+'</a></div></div></header>'
def footer():return '<section class="case-contact wrap"><span class="overline">'+tr(('Twój kolejny krok','Your next step'))+'</span>'+tr(('Porozmawiajmy o Twoich danych.','Let’s talk about your data.'),'h2')+'<p>'+tr(('Pokaż nam problem. Dobierzemy zakres, dane i sposób sprawdzenia rozwiązania.','Show us the problem. We will define the scope, data and a way to evaluate the solution.'))+'</p><a class="button primary" href="https://antillia.tech/#contact">'+tr(('Omów swój projekt','Discuss your project'))+ARROW+'</a></section><footer class="wrap"><div class="footer-top"><a class="brand" href="https://antillia.tech">Antillia</a>'+tr(('Od pomysłu do działającego rozwiązania.','From an idea to a working solution.'))+'<a href="index.html">Portfolio ↑</a></div><div class="footer-bottom"><span>© 2026 Antillia · Applied intelligence</span><button class="motion-toggle" data-motion>'+tr(('Animacje: włączone','Motion: enabled'))+'</button></div></footer>'
def shell(title,body):return '<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+' · Antillia</title><meta name="description" content="'+esc(title)+' — Antillia: model, pipeline, measured results and real examples."><link rel="icon" href="case-study-assets/antillia.svg"><link rel="stylesheet" href="case-study-assets/antillia-site.css"><link rel="stylesheet" href="case-study-assets/cases.css"><script defer src="case-study-assets/cases.js"></script></head><body class="case-page"><div class="case-ambient" aria-hidden="true"></div>'+header()+'<main id="main">'+body+'</main>'+footer()+'</body></html>'
for number,c in enumerate(CASES,1):
    slug=c['slug'];rows,metric,hero,unit,scope=benchmark(c);d=evidence[slug]
    (A/f'{slug}-architecture.svg').write_text(architecture(c),encoding='utf8');(A/f'{slug}-weights.svg').write_text(model_visual(c),encoding='utf8')
    preview=A/'previews';preview.mkdir(exist_ok=True);shutil.copyfile(R/c['folder']/'reports/screenshots/1440-pl.png',preview/f'{slug}.png')
    metric_html=''.join('<div class="benchmark-row"><div><span>'+esc(name)+'</span><strong>'+f'{value:.3f}'+'</strong></div><div class="bar-track"><i style="--bar:'+str(value/max(v for _,v in rows)*100)+'%"></i></div></div>' for name,value in rows)
    features=''.join('<article><span class="case-number">0'+str(i+1)+'</span>'+tr((f[0],f[1]),'h3')+tr((f[2],f[3]),'p')+'</article>' for i,f in enumerate(c['features']))
    uses=''.join('<article><span class="case-number">0'+str(i+1)+'</span>'+tr((f[0],f[1]),'h3')+tr((f[2],f[3]),'p')+'</article>' for i,f in enumerate(c['uses']))
    flow=''.join('<div class="flow-node"><span>0'+str(i+1)+'</span>'+tr(step,'strong')+'</div>' for i,step in enumerate(c['steps']))
    body='<section class="case-hero wrap"><div><a class="case-back" href="index.html">← Portfolio / '+esc(c['name'])+'</a><p class="eyebrow"><span class="status-dot"></span>'+tr(c['category'])+' <b>/</b> CASE STUDY '+f'{number:02d}'+'</p><h1>'+tr(c['headline'])+'<br>'+tr(c['accent'],'em')+'</h1>'+tr(c['intro'],'p','case-lead')+'<div class="hero-actions"><a class="button primary" href="#results">'+tr(('Zobacz wyniki','Explore results'))+ARROW+'</a><a class="text-link" href="#model">'+tr(('Zajrzyj do modelu','Inside the model'))+' ↓</a></div></div><div class="hero-evidence"><div class="evidence-toolbar"><span>'+esc(c['name'].upper())+' / MEASURED</span><i></i></div><div class="hero-value">'+hero+'</div>'+tr(unit,'p','metric-unit')+tr(scope,'p','metric-scope')+'<img class="hero-model" src="case-study-assets/'+slug+'-weights.svg" alt="Actual model evidence"><span class="tiny-label">SAVED ARTIFACTS / REPRODUCIBLE RESULTS</span></div></section>'
    body+='<section class="wrap case-overview" id="overview"><div><span class="overline">'+tr(('Zadanie','The task'))+'</span>'+tr(c['problem'],'h2')+'</div>'+tr(c['problem_body'],'p')+'</section><section class="wrap feature-grid">'+features+'</section>'
    body+='<section class="wrap section" id="results"><div class="case-heading"><div><span class="overline">'+tr(('Zmierzony wynik','Measured performance'))+'</span>'+tr(('Wynik z kontekstem.','Results with context.'),'h2')+'</div><div>'+tr(scope,'p')+'<span class="tiny-label">'+esc(metric)+'</span></div></div><div class="result-layout"><div class="benchmark">'+metric_html+'</div><aside class="method-note"><span class="tiny-label">EVALUATION PROTOCOL</span>'+tr(('Wybór na walidacji. Ocena na osobnym teście.','Selection on validation. Evaluation on a separate test.'),'h3')+'<p>'+tr(('Metryki pokazują wynik konkretnego eksperymentu. Pełne konfiguracje, podziały i wyniki znajdują się w repozytorium.','Metrics describe this particular experiment. Full configurations, splits and results are included in the repository.'))+'</p><a class="text-link" href="https://github.com/Flyingzaptop/antillia-ml-portfolio/tree/main/'+c['folder']+'">'+tr(('Kod i raporty','Code and reports'))+ARROW+'</a></aside></div></section>'
    body+='<section class="pipeline-section"><div class="wrap"><span class="overline">ML ENGINEERING</span>'+tr(('Od wejścia do decyzji.','From input to decision.'),'h2')+'<div class="pipeline">'+flow+'</div><div class="engineering-strip"><span>TRAIN / VALIDATION / TEST</span><span>VERSIONED ARTIFACTS</span><span>LOCAL INFERENCE</span><span>MEASURED OUTPUT</span></div></div></section>'
    body+='<section class="wrap section" id="model"><div class="case-heading"><div><span class="overline">'+tr(('Wewnątrz rozwiązania','Inside the solution'))+'</span>'+tr(('Architektura, którą można prześledzić.','An architecture you can follow.'),'h2')+'</div></div><figure class="model-figure"><div class="diagram-scroll"><img src="case-study-assets/'+slug+'-architecture.svg" alt="'+esc(c['name'])+' architecture"></div><figcaption>'+tr(c['model_note'])+'</figcaption></figure><div class="weights-layout"><figure><img src="case-study-assets/'+slug+'-weights.svg" alt="'+esc(c['name'])+' model visualization"><figcaption>'+tr((d['caption_pl'],d['caption_en']))+'</figcaption></figure><div><span class="overline">'+tr(('Rzeczywisty artefakt','Actual model artifact'))+'</span>'+tr(('Model ma strukturę. I zapisane parametry.','A model has structure. And saved parameters.'),'h3')+tr(('Ta ilustracja została wygenerowana z wag lub reprezentacji używanych w projekcie. Ułatwia rozmowę o architekturze, ale sama nie wyjaśnia każdej decyzji modelu.','This illustration was generated from weights or representations used in the project. It helps explain the architecture, but does not by itself explain every model decision.'),'p')+'<span class="stack">'+esc(c['stack'])+'</span></div></div></section>'
    body+='<section class="wrap example-section"><div><span class="overline">'+tr(('Przykład działania','In practice'))+'</span>'+tr(('Konkretny input. Czytelny output.','A concrete input. A clear output.'),'h2')+tr(c['example'],'p')+'</div><div class="browser-frame"><div class="browser-dots"><i></i><i></i><i></i><span>'+esc(c['name'])+' / WORKING APPLICATION</span></div><img loading="lazy" src="case-study-assets/previews/'+slug+'.png" alt="'+esc(c['name'])+' working application screenshot"></div></section>'
    body+='<section class="wrap section" id="uses"><span class="overline">'+tr(('Możliwe zastosowania','Potential applications'))+'</span>'+tr(('Gdzie ten kierunek ma sens.','Where this approach can help.'),'h2')+'<div class="use-grid">'+uses+'</div></section><section class="wrap limits-section"><div><span class="overline">'+tr(('Granice rozwiązania','Solution boundaries'))+'</span>'+tr(('Co już wiemy. Co trzeba sprawdzić dalej.','What we know. What needs further evaluation.'),'h2')+'</div><div>'+tr(c['limits'],'p')+'<a class="source-link" href="'+esc(c['source_url'])+'" target="_blank" rel="noreferrer">'+esc(c['source'])+' ↗</a><p class="case-demo-note">'+tr(('Projekt demonstracyjny zespołu Antillia. Scenariusze zastosowań opisują możliwości adaptacji; nie są deklaracją wdrożenia u klienta.','An Antillia demonstration project. Application scenarios describe adaptation opportunities, not claims of a client deployment.'))+'</p></div></section><section class="wrap artifact-links"><a class="button primary" href="https://github.com/Flyingzaptop/antillia-ml-portfolio/releases/download/v1.0.0/'+c['folder']+'.zip">'+tr(('Pobierz projekt','Download project'))+ARROW+'</a><a class="text-link" href="https://github.com/Flyingzaptop/antillia-ml-portfolio/tree/main/'+c['folder']+'">GitHub '+ARROW+'</a><a class="text-link" href="index.html">'+tr(('Wszystkie projekty','All projects'))+' →</a></section>'
    (R/(slug+'.html')).write_text(shell(c['name']+' — '+c['category'][0],body),encoding='utf8')
cards=''
for i,c in enumerate(CASES,1):
    _,_,value,unit,_=benchmark(c)
    cards+='<a class="case-index-card" href="'+c['slug']+'.html"><div class="card-top"><span>0'+str(i)+' / '+esc(c['name'])+'</span>'+ARROW+'</div><img src="case-study-assets/'+c['slug']+'-weights.svg" alt="'+esc(c['name'])+' model evidence"><div><span class="overline">'+tr(c['category'])+'</span><h3>'+esc(c['name'])+'</h3>'+tr(c['intro'],'p')+'<div class="index-metric"><strong>'+value+'</strong>'+tr(unit)+'</div></div></a>'
body='<section class="wrap index-hero"><p class="eyebrow"><span class="status-dot"></span>ANTILLIA / APPLIED INTELLIGENCE</p><h1>'+tr(('Od danych','From data'))+'<br>'+tr(('do działającego rozwiązania.','to a working solution.'),'em')+'</h1>'+tr(('Sześć projektów machine learning i lokalny asystent wiedzy. Poznaj ich zadania, architekturę, mierzone wyniki i możliwości zastosowania.','Six machine-learning projects and a local knowledge assistant. Explore their purpose, architecture, measured results and application opportunities.'),'p')+'<div class="index-facts"><span>07 '+tr(('projektów','projects'))+'</span><span>PL / EN</span><span>'+tr(('Lokalne modele','Local models'))+'</span><span>'+tr(('Odtwarzalne wyniki','Reproducible results'))+'</span></div></section><section class="wrap case-index" id="results">'+cards+'</section>'
(R/'index.html').write_text(shell('Machine learning portfolio',body),encoding='utf8')
(R/'CASE_STUDIES.md').write_text('# Antillia case-study pages\n\nOpen index.html directly, or run `py -3.12 tools/serve_cases.py` and visit http://127.0.0.1:8090 .\n\n'+''.join(f'- [{c["name"]}]({c["slug"]}.html)\n' for c in CASES)+'\nDesign uses the original antillia.tech site.css, its Manrope/DM Sans fonts and Antillia mark. Font licenses are in case-study-assets/fonts/. Diagrams are original SVG, model visualizations derive from saved artifacts, and screenshots are actual app captures. PL/EN is switched locally without external APIs. These files are prepared for later integration into antillia.tech; production site has not been modified.\n',encoding='utf8')
print('Built seven bilingual case studies and index in Portfolio root.')
